# corepack enable ; les extraits de fichiers de la racine (package.json, Dockerfile) sont situés.
# Prérequis : apply-lint-passe-2.sh.
# Usage (racine du repo) : bash apply-docs-mise-en-route.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null | grep -qF "Ce lanceur, à chaque appel"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Le typecheck et le lint" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-lint-passe-2.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/mise-en-route.mdx" "apps/web/src/features/docs/lib/code.utils.ts" "apps/web/src/features/docs/lib/fenceIndex.ts")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Ce lanceur, à chaque appel" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
